    '收藏航线': 'Save route', '已收藏航线 ★': 'Route saved ★', '已取消收藏': 'Favorite removed',
    '品牌介绍 ': 'About', '芒果航空（Mango Air）是一家以「温暖、轻快、可负担」为基因的虚拟演示航司。我们相信飞行不该是昂贵的距离——一抹芒果金，就能点亮整片深蓝天空。':
      'Mango Air is a virtual demo airline built on being warm, light and affordable. We believe flying should not be an expensive distance — a touch of mango gold lights up the whole deep-blue sky.',
    '从清晨第一班短途摆渡，到跨越高原的长航宽体，芒果航空用年轻机队与贴心舱享，陪伴每一位旅客奔赴自己的山海。':
      'From the first short hop of the morning to long-haul wide-bodies crossing plateaus, our young fleet and warm cabins accompany every traveler to their own mountains and seas.',
    '年轻机队': 'Young Fleet', '透明定价': 'Transparent Pricing', '温暖服务': 'Warm Service',
    '座位数': 'Seats', '最大航程': 'Max Range',
    '芒果航空是天和联盟的品牌演示成员。天和联盟以深蓝色航迹为标志，象征跨越山海的连接。成员航司间共享枢纽机场、互认常旅客里程，并提供贵宾厅与中转保障互通。':
      'Mango Air is a demo member of the Tianhe Alliance, symbolized by deep-blue flight paths connecting across mountains and seas. Members share hubs, recognize each other\'s miles, and offer lounge and transfer benefits.',
    'ℹ️ 联盟合作关系为品牌演示设定，非现实联盟认证': 'ℹ️ Alliance partnership is a demo setting, not a real-world certification',
    '声明': 'Disclaimer',
    '本网站为芒果航空 Mango Air 品牌演示站点。页面中的航班、时刻、票价、余票、准点率、机队与联盟信息均为虚构演示数据，不构成真实航空运输服务或要约。本站不接入真实支付、不出具真实客票。如需乘坐真实航班，请前往真实航空公司官方渠道。':
      'This website is a brand demo for Mango Air. All flights, schedules, fares, seat availability, on-time rates, fleet and alliance information are fictional demo data and do not constitute a real air service or offer. No real payment is connected and no real tickets are issued. For real travel, please visit a real airline.',
