    '「天和联盟」为芒果航空品牌演示中的虚构联盟，现实并不存在该联盟，因此不存在可对接的「现实天和联盟航班」。本设置对接的是标准航班数据接口：任何返回标准航班 JSON 的端点（真实航司 API、GDS/NDC 聚合或自建后端）均可接入，字段约定见 js/api.js 顶部注释。请求失败将自动降级为本地演示数据。': '"Tianhe Alliance" is a fictional alliance in the Mango Air brand demo; it does not exist in reality, so there are no "real Tianhe Alliance flights" to connect to. This setting connects to a standard flight data API: any endpoint returning standard flight JSON (real airline APIs, GDS/NDC aggregators, or your own backend) can be integrated. Field conventions are documented at the top of js/api.js. Failed requests automatically fall back to local demo data.',
