    '航线与目的地': 'Rutas y Destinos', '芒果航空网络覆盖 {n} 座城市（演示航线网络） · 点击航线卡片即可搜索': 'Mango Air sirve {n} ciudades (red demo) · toca una tarjeta de ruta para buscar',
