    '支线航点经天和联盟枢纽互通，一票中转、行李直挂（演示设定）。': 'Las ciudades regionales se conectan mediante hubs de la Alianza Tianhe — conexión con un solo billete y equipaje facturado directo (demo).',
    '收藏航线': 'Guardar ruta', '已收藏航线 ★': 'Ruta guardada ★', '已取消收藏': 'Favorito eliminado',
    '品牌介绍 ': 'Nosotros', '芒果航空（Mango Air）是一家以「温暖、轻快、可负担」为基因的虚拟演示航司。我们相信飞行不该是昂贵的距离——一抹芒果金，就能点亮整片深蓝天空。':
      'Mango Air es una aerolínea demo virtual basada en ser cálida, ligera y asequible. Creemos que volar no debería ser una distancia costosa — un toque de dorado mango ilumina todo el cielo azul profundo.',
    '从清晨第一班短途摆渡，到跨越高原的长航宽体，芒果航空用年轻机队与贴心舱享，陪伴每一位旅客奔赴自己的山海。':
      'Desde el primer vuelo corto de la mañana hasta los wide-bodies de largo alcance que cruzan mesetas, nuestra flota joven y cabinas cálidas acompañan a cada viajero hacia sus propias montañas y mares.',
    '年轻机队': 'Flota Joven', '透明定价': 'Precios Transparentes', '温暖服务': 'Servicio Cálido',
    '座位数': 'Asientos', '最大航程': 'Autonomía Máx.',
    '芒果航空是天和联盟的品牌演示成员。天和联盟以深蓝色航迹为标志，象征跨越山海的连接。成员航司间共享枢纽机场、互认常旅客里程，并提供贵宾厅与中转保障互通。':
      'Mango Air es miembro demo de la Alianza Tianhe, simbolizada por trayectorias azul profundo que conectan montañas y mares. Los miembros comparten hubs, reconocen sus millas y ofrecen salas VIP y conexiones.',
    'ℹ️ 联盟合作关系为品牌演示设定，非现实联盟认证': 'ℹ️ La alianza es una configuración demo, no una certificación real',
    '声明': 'Aviso Legal',
    '本网站为芒果航空 Mango Air 品牌演示站点。页面中的航班、时刻、票价、余票、准点率、机队与联盟信息均为虚构演示数据，不构成真实航空运输服务或要约。本站不接入真实支付、不出具真实客票。如需乘坐真实航班，请前往真实航空公司官方渠道。':
      'Este sitio es una demo de marca de Mango Air. Todos los vuelos, horarios, tarifas, plazas, puntualidad, flota e información de alianza son datos ficticios de demostración y no constituyen un servicio ni una oferta real. No hay pago real ni billetes reales. Para viajar de verdad, acude a una aerolínea real.',
