    '保存并启用': 'Guardar y activar',
    '关于对接': 'Acerca de la integración',
    '「天和联盟」为芒果航空品牌演示中的虚构联盟，现实并不存在该联盟，因此不存在可对接的「现实天和联盟航班」。本设置对接的是标准航班数据接口：任何返回标准航班 JSON 的端点（真实航司 API、GDS/NDC 聚合或自建后端）均可接入，字段约定见 js/api.js 顶部注释。请求失败将自动降级为本地演示数据。': '«Tianhe Alliance» es una alianza ficticia de la demostración de Mango Air; no existe en la realidad, por lo que no hay «vuelos reales de Tianhe Alliance» a los que conectarse. Este ajuste se conecta a una API estándar de datos de vuelos: cualquier endpoint que devuelva JSON de vuelos estándar (API de aerolíneas reales, agregadores GDS/NDC o tu propio backend) puede integrarse. Las convenciones de campos están documentadas al inicio de js/api.js. Si la petición falla, se usan automáticamente los datos de demostración locales.',
