    '天和联盟枢纽': 'Hub de l\'Alliance Tianhe', '中转连线': 'Lignes de Correspondance', '天和联盟中转网络': 'Réseau de Correspondances de l\'Alliance Tianhe',
    '支线航点经天和联盟枢纽互通，一票中转、行李直挂（演示设定）。': 'Les villes régionales se relient via les hubs de l\'Alliance Tianhe — correspondance sur un seul billet, bagages enregistrés direct (démo).',
    '收藏航线': 'Enregistrer la route', '已收藏航线 ★': 'Route enregistrée ★', '已取消收藏': 'Favori supprimé',
    '品牌介绍 ': 'À propos', '芒果航空（Mango Air）是一家以「温暖、轻快、可负担」为基因的虚拟演示航司。我们相信飞行不该是昂贵的距离——一抹芒果金，就能点亮整片深蓝天空。':
      'Mango Air est une compagnie démo virtuelle fondée sur la chaleur, la légèreté et l\'accessibilité. Nous croyons que voler ne devrait pas être une distance coûteuse — une touche de doré mango illumine tout le ciel bleu profond.',
    '从清晨第一班短途摆渡，到跨越高原的长航宽体，芒果航空用年轻机队与贴心舱享，陪伴每一位旅客奔赴自己的山海。':
      'Du premier saut de puce du matin aux long-courriers larges franchissant les plateaux, notre flotte jeune et nos cabines chaleureuses accompagnent chaque voyageur vers ses propres monts et mers.',
    '年轻机队': 'Flotte Jeune', '透明定价': 'Tarifs Transparents', '温暖服务': 'Service Chaleureux',
    '座位数': 'Sièges', '最大航程': 'Rayon Max.',
    '芒果航空是天和联盟的品牌演示成员。天和联盟以深蓝色航迹为标志，象征跨越山海的连接。成员航司间共享枢纽机场、互认常旅客里程，并提供贵宾厅与中转保障互通。':
      'Mango Air est un membre démo de l\'Alliance Tianhe, symbolisée par des trajectoires bleu profond reliant monts et mers. Les membres partagent leurs hubs, reconnaissent leurs miles et offrent salons et correspondances.',
    'ℹ️ 联盟合作关系为品牌演示设定，非现实联盟认证': 'ℹ️ Le partenariat d\'alliance est un réglage démo, pas une certification réelle',
    '声明': 'Mentions Légales',
    '本网站为芒果航空 Mango Air 品牌演示站点。页面中的航班、时刻、票价、余票、准点率、机队与联盟信息均为虚构演示数据，不构成真实航空运输服务或要约。本站不接入真实支付、不出具真实客票。如需乘坐真实航班，请前往真实航空公司官方渠道。':
      'Ce site est une démo de marque pour Mango Air. Tous les vols, horaires, tarifs, places, ponctualité, flotte et informations d\'alliance sont des données fictives de démonstration et ne constituent ni un service ni une offre réels. Aucun paiement réel n\'est connecté et aucun billet réel n\'est émis. Pour voyager vraiment, adressez-vous à une vraie compagnie.',
