    '保存并启用': 'Enregistrer et activer',
    '关于对接': 'À propos de l\'intégration',
    '「天和联盟」为芒果航空品牌演示中的虚构联盟，现实并不存在该联盟，因此不存在可对接的「现实天和联盟航班」。本设置对接的是标准航班数据接口：任何返回标准航班 JSON 的端点（真实航司 API、GDS/NDC 聚合或自建后端）均可接入，字段约定见 js/api.js 顶部注释。请求失败将自动降级为本地演示数据。': '« Tianhe Alliance » est une alliance fictive de la démonstration Mango Air ; elle n\'existe pas dans la réalité, il n\'y a donc aucun « vol réel Tianhe Alliance » à connecter. Ce réglage se connecte à une API de données de vols standard : tout point de terminaison renvoyant du JSON de vols standard (API de compagnies réelles, agrégateurs GDS/NDC ou votre propre backend) peut être intégré. Les conventions de champs sont documentées en haut de js/api.js. En cas d\'échec, le système bascule automatiquement sur les données de démonstration locales.',
