    '请修正表单错误': 'Bitte Formularfehler korrigieren', '该手机号已注册，请直接登录': 'Diese Telefonnummer ist registriert — bitte anmelden',
    '密码错误': 'Falsches Passwort', '注册成功，欢迎加入芒果航空！': 'Registrierung erfolgreich — willkommen bei Mango Air!', '登录成功': 'Anmeldung erfolgreich',
    '航线与目的地': 'Routen & Reiseziele', '芒果航空网络覆盖 {n} 座城市（演示航线网络） · 点击航线卡片即可搜索': 'Mango Air bedient {n} Städte (Demo-Netz) · Routenkarte antippen zum Suchen',
    '天和联盟枢纽': 'Tianhe-Allianz-Hub', '中转连线': 'Verbindungsrouten', '天和联盟中转网络': 'Umsteigenetz der Tianhe-Allianz',
    '支线航点经天和联盟枢纽互通，一票中转、行李直挂（演示设定）。': 'Regionale Städte verbinden sich über Hubs der Tianhe-Allianz — ein Ticket, durchgechecktes Gepäck (Demo).',
    '收藏航线': 'Route speichern', '已收藏航线 ★': 'Route gespeichert ★', '已取消收藏': 'Favorit entfernt',
    '品牌介绍 ': 'Über uns', '芒果航空（Mango Air）是一家以「温暖、轻快、可负担」为基因的虚拟演示航司。我们相信飞行不该是昂贵的距离——一抹芒果金，就能点亮整片深蓝天空。':
      'Mango Air ist eine virtuelle Demo-Airline mit den Genen „warm, leicht, leistbar“. Wir glauben, Fliegen sollte keine teure Distanz sein — ein Hauch Mango-Gold erhellt den ganzen tiefblauen Himmel.',
    '从清晨第一班短途摆渡，到跨越高原的长航宽体，芒果航空用年轻机队与贴心舱享，陪伴每一位旅客奔赴自己的山海。':
      'Vom ersten Kurzflug am Morgen bis zu Langstrecken-Widebodys über Plateaus begleiten junge Flotte und warme Kabinen jeden Reisenden zu seinen eigenen Bergen und Meeren.',
    '年轻机队': 'Junge Flotte', '透明定价': 'Transparente Preise', '温暖服务': 'Warmer Service',
    '座位数': 'Sitzplätze', '最大航程': 'Max. Reichweite',
    '芒果航空是天和联盟的品牌演示成员。天和联盟以深蓝色航迹为标志，象征跨越山海的连接。成员航司间共享枢纽机场、互认常旅客里程，并提供贵宾厅与中转保障互通。':
      'Mango Air ist Demo-Mitglied der Tianhe-Allianz, symbolisiert durch tiefblaue Flugpfade, die Berge und Meere verbinden. Mitglieder teilen Hubs, erkennen Meilen gegenseitig an und bieten Lounge- und Umsteigeleistungen.',
    'ℹ️ 联盟合作关系为品牌演示设定，非现实联盟认证': 'ℹ️ Die Allianz-Partnerschaft ist eine Demo-Einstellung, keine reale Zertifizierung',
    '声明': 'Haftungsausschluss',
    '本网站为芒果航空 Mango Air 品牌演示站点。页面中的航班、时刻、票价、余票、准点率、机队与联盟信息均为虚构演示数据，不构成真实航空运输服务或要约。本站不接入真实支付、不出具真实客票。如需乘坐真实航班，请前往真实航空公司官方渠道。':
      'Diese Website ist eine Marken-Demo für Mango Air. Alle Flüge, Zeiten, Preise, Plätze, Pünktlichkeit, Flotte und Allianz-Angaben sind fiktive Demodaten und stellen keinen echten Luftverkehrsdienst und kein Angebot dar. Es gibt keine echte Zahlung und keine echten Tickets. Für echte Reisen wenden Sie sich an eine echte Airline.',
