    '1. 欢迎乘坐芒果航空！使用 AI 低价功能，帮您找到更划算的出发日。<br>2. 您关注的航线价格有波动（模拟消息）。':
      '1. Willkommen an Bord von Mango Air! Nutzen Sie KI-Tiefpreise für günstigere Abflugtage.<br>2. Die Preise Ihrer beobachteten Routen haben sich geändert (simulierte Nachricht).',    '数据源': 'Datenquelle',
