    '保存并启用': 'Speichern & aktivieren',
    '关于对接': 'Über die Anbindung',
    '「天和联盟」为芒果航空品牌演示中的虚构联盟，现实并不存在该联盟，因此不存在可对接的「现实天和联盟航班」。本设置对接的是标准航班数据接口：任何返回标准航班 JSON 的端点（真实航司 API、GDS/NDC 聚合或自建后端）均可接入，字段约定见 js/api.js 顶部注释。请求失败将自动降级为本地演示数据。': '„Tianhe Alliance“ ist eine fiktive Allianz der Mango-Air-Demo und existiert in der Realität nicht – es gibt also keine „echten Tianhe-Alliance-Flüge“ zur Anbindung. Diese Einstellung verbindet sich mit einer Standard-Flugdaten-API: Jeder Endpunkt, der Standard-Flug-JSON liefert (echte Airline-APIs, GDS/NDC-Aggregatoren oder eigenes Backend), kann angebunden werden. Feldkonventionen stehen im Kopf von js/api.js. Fehlgeschlagene Anfragen weichen automatisch auf lokale Demodaten aus.',
