    '品牌介绍 ': 'ブランド', '芒果航空（Mango Air）是一家以「温暖、轻快、可负担」为基因的虚拟演示航司。我们相信飞行不该是昂贵的距离——一抹芒果金，就能点亮整片深蓝天空。':
      'マンゴエア（Mango Air）は「温かさ・軽やかさ・手頃さ」を遺伝子にもつバーチャルデモ航空会社。飛ぶことは高価な距離であるべきではない——一抹のマンゴーゴールドが、深い青の空全体を照らします。',
    '从清晨第一班短途摆渡，到跨越高原的长航宽体，芒果航空用年轻机队与贴心舱享，陪伴每一位旅客奔赴自己的山海。':
      '早朝最初の短距離フライトから、高原を越える長距離ワイドボディまで、若い機材と心尽くしのキャビンで、すべての旅客の山海への旅に寄り添います。',
    '年轻机队': '若い機材', '透明定价': '透明な料金', '温暖服务': '温かなサービス',
    '座位数': '座席数', '最大航程': '最大航続距離',
    '芒果航空是天和联盟的品牌演示成员。天和联盟以深蓝色航迹为标志，象征跨越山海的连接。成员航司间共享枢纽机场、互认常旅客里程，并提供贵宾厅与中转保障互通。':
      'マンゴエアは天和連盟のブランドデモメンバー。深い青の航跡を象徴とし、山海を越えるつながりを表します。メンバーはハブ空港を共有し、マイレージを相互に認め、ラウンジと乗継保証を提供します。',
    'ℹ️ 联盟合作关系为品牌演示设定，非现实联盟认证': 'ℹ️ 同盟関係はブランドデモ設定であり、実際の同盟認定ではありません',
    '声明': '免責事項',
    '本网站为芒果航空 Mango Air 品牌演示站点。页面中的航班、时刻、票价、余票、准点率、机队与联盟信息均为虚构演示数据，不构成真实航空运输服务或要约。本站不接入真实支付、不出具真实客票。如需乘坐真实航班，请前往真实航空公司官方渠道。':
      '本サイトはマンゴエア Mango Air のブランドデモサイトです。フライト・時刻・料金・空席・定時運航率・機材・同盟情報はすべて架空のデモデータであり、実際の航空運送サービスや申込の提示ではありません。実際の決済は接続しておらず、実際の航空券も発行しません。実際の空の旅には、実際の航空会社をご利用ください。',
