    '品牌介绍 ': '브랜드', '芒果航空（Mango Air）是一家以「温暖、轻快、可负担」为基因的虚拟演示航司。我们相信飞行不该是昂贵的距离——一抹芒果金，就能点亮整片深蓝天空。':
      '망고에어(Mango Air)는 「따뜻함, 가벼움, 부담 없음」을 유전자로 하는 가상 데모 항공사입니다. 비행은 값비싼 거리가 아니어야 합니다—망고 골드 한 톤이 깊은 푸른 하늘 전체를 밝힙니다.',
    '从清晨第一班短途摆渡，到跨越高原的长航宽体，芒果航空用年轻机队与贴心舱享，陪伴每一位旅客奔赴自己的山海。':
      '이른 아침 첫 단거리 운항부터 고원을 넘는 장거리 와이드보디까지, 젊은 기단과 정성스러운 캐빈으로 모든 여행자의 산과 바다를 함께합니다.',
    '年轻机队': '젊은 기단', '透明定价': '투명한 요금', '温暖服务': '따뜻한 서비스',
    '座位数': '좌석 수', '最大航程': '최대 항속거리',
    '芒果航空是天和联盟的品牌演示成员。天和联盟以深蓝色航迹为标志，象征跨越山海的连接。成员航司间共享枢纽机场、互认常旅客里程，并提供贵宾厅与中转保障互通。':
      '망고에어는 톈허 동맹의 브랜드 데모 회원입니다. 톈허 동맹은 깊은 푸른 항적을 상징으로, 산과 바다를 넘는 연결을 뜻합니다. 회원사는 허브 공항을 공유하고 마일을 상호 인정하며 라운지와 환승 지원을 제공합니다.',
    'ℹ️ 联盟合作关系为品牌演示设定，非现实联盟认证': 'ℹ️ 동맹 관계는 브랜드 데모 설정이며 실제 동맹 인증이 아닙니다',
    '声明': '고지',
    '本网站为芒果航空 Mango Air 品牌演示站点。页面中的航班、时刻、票价、余票、准点率、机队与联盟信息均为虚构演示数据，不构成真实航空运输服务或要约。本站不接入真实支付、不出具真实客票。如需乘坐真实航班，请前往真实航空公司官方渠道。':
      '본 사이트는 망고에어 Mango Air 브랜드 데모 사이트입니다. 항공편, 시각, 요금, 좌석, 정시운행률, 기단, 동맹 정보는 모두 가상의 데모 데이터이며 실제 항공 운송 서비스나 청약이 아닙니다. 실제 결제는 연동되지 않으며 실제 항공권도 발행되지 않습니다. 실제 탑승은 실제 항공사를 이용하세요.',
