    '支线航点经天和联盟枢纽互通，一票中转、行李直挂（演示设定）。': 'Региональные аэропорты связаны через хабы Альянса Тяньхэ — по одному билету с прямым трансфертом багажа (демо).',
    '收藏航线': 'Сохранить маршрут',
    '已收藏航线 ★': 'Маршрут сохранён ★',
    '已取消收藏': 'Удалено из избранного',
    '品牌介绍 ': 'О нас',
    '芒果航空（Mango Air）是一家以「温暖、轻快、可负担」为基因的虚拟演示航司。我们相信飞行不该是昂贵的距离——一抹芒果金，就能点亮整片深蓝天空。': 'Mango Air — виртуальная демо-авиакомпания с характером «тёплый, лёгкий, доступный». Мы верим, что полёт не должен быть дорогим расстоянием — капля золота манго освещает всё тёмно-синее небо.',
    '从清晨第一班短途摆渡，到跨越高原的长航宽体，芒果航空用年轻机队与贴心舱享，陪伴每一位旅客奔赴自己的山海。': 'От первого короткого рейса раннего утра до дальнемагистральных широкофюзеляжных через плато — молодой флот и заботливые салоны Mango Air сопровождают каждого пассажира к его собственным горам и морям.',
    '年轻机队': 'Молодой флот',
    '透明定价': 'Прозрачные цены',
    '温暖服务': 'Тёплый сервис',
    '座位数': 'Мест',
    '最大航程': 'Макс. дальность',
    '芒果航空是天和联盟的品牌演示成员。天和联盟以深蓝色航迹为标志，象征跨越山海的连接。成员航司间共享枢纽机场、互认常旅客里程，并提供贵宾厅与中转保障互通。': 'Mango Air — демо-участник Альянса Тяньхэ, символ которого — тёмно-синие маршруты, соединяющие горы и моря. Авиакомпании-участники делятся хабами, признают мили друг друга и предоставляют взаимный доступ в лаунжи и сервис пересадок.',
    'ℹ️ 联盟合作关系为品牌演示设定，非现实联盟认证': 'ℹ️ Партнёрство в альянсе — демо-настройка, не реальная сертификация',
    '声明': 'Отказ от ответственности',
    '本网站为芒果航空 Mango Air 品牌演示站点。页面中的航班、时刻、票价、余票、准点率、机队与联盟信息均为虚构演示数据，不构成真实航空运输服务或要约。本站不接入真实支付、不出具真实客票。如需乘坐真实航班，请前往真实航空公司官方渠道。': 'Этот сайт — бренд-демо Mango Air. Все рейсы, расписания, тарифы, наличие мест, пунктуальность, данные флота и альянса — вымышленные демо-данные, не являющиеся реальной авиаперевозкой или офертой. Реальная оплата не подключена, реальные билеты не выдаются. Для реальных поездок обращайтесь к реальным авиакомпаниям.',
