    '1. 欢迎乘坐芒果航空！使用 AI 低价功能，帮您找到更划算的出发日。<br>2. 您关注的航线价格有波动（模拟消息）。': '1. Добро пожаловать на борт Mango Air! Используйте ИИ-тарифы, чтобы найти выгодные даты вылета.<br>2. Цены на отслеживаемых маршрутах изменились (демо-сообщение).',
