    '保存并启用': 'Сохранить и включить',
    '关于对接': 'Об интеграции',
    '「天和联盟」为芒果航空品牌演示中的虚构联盟，现实并不存在该联盟，因此不存在可对接的「现实天和联盟航班」。本设置对接的是标准航班数据接口：任何返回标准航班 JSON 的端点（真实航司 API、GDS/NDC 聚合或自建后端）均可接入，字段约定见 js/api.js 顶部注释。请求失败将自动降级为本地演示数据。': '«Альянс Тяньхэ» — вымышленный альянс демонстрации бренда Mango Air, он не существует в реальности, поэтому «реальных рейсов альянса Тяньхэ» для подключения нет. Эта настройка подключается к стандартному API данных о рейсах: подойдёт любой эндпоинт, возвращающий стандартный JSON рейсов (API реальных авиакомпаний, агрегаторы GDS/NDC или собственный бэкенд). Соглашение о полях — в начале js/api.js. При ошибке запроса автоматически выполняется откат к локальным демо-данным.',
